INSERT INTO public."COMPETENCY" ("COMPETENCY_ID", "NAME", "DESCRIPTION", "WEIGHT", "CREATED_AT", "CREATED_BY", "STATE", "UPDATED_AT", "UPDATED_BY") VALUES (1, 'Planificacion estrategica de metas', 'Define objetivos claros alineados al plan del modulo y estructura metricas para medir el avance.', NULL, '2025-09-25 17:03:01.056887', NULL, 'A', '2025-09-25 17:03:01.056887', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."COMPETENCY" ("COMPETENCY_ID", "NAME", "DESCRIPTION", "WEIGHT", "CREATED_AT", "CREATED_BY", "STATE", "UPDATED_AT", "UPDATED_BY") VALUES (2, 'Orientacion a resultados', 'Mantiene el foco en el cumplimiento oportuno de los entregables y compromisos asumidos con el equipo.', NULL, '2025-09-25 17:03:01.056887', NULL, 'A', '2025-09-25 17:03:01.056887', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."COMPETENCY" ("COMPETENCY_ID", "NAME", "DESCRIPTION", "WEIGHT", "CREATED_AT", "CREATED_BY", "STATE", "UPDATED_AT", "UPDATED_BY") VALUES (3, 'Gestion del tiempo', 'Organiza y prioriza actividades para cumplir con los plazos establecidos sin sacrificar la calidad.', NULL, '2025-09-25 17:03:01.056887', NULL, 'A', '2025-09-25 17:03:01.056887', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."COMPETENCY" ("COMPETENCY_ID", "NAME", "DESCRIPTION", "WEIGHT", "CREATED_AT", "CREATED_BY", "STATE", "UPDATED_AT", "UPDATED_BY") VALUES (4, 'Trabajo en equipo', 'Colabora activamente, comparte informacion y aporta al logro colectivo de los objetivos del modulo.', NULL, '2025-09-25 17:03:01.056887', NULL, 'A', '2025-09-25 17:03:01.056887', NULL) ON CONFLICT DO NOTHING;
