INSERT INTO public."COMPETENCY" ("COMPETENCY_ID", "NAME", "DESCRIPTION", "WEIGHT", "CREATED_AT", "CREATED_BY", "STATE", "UPDATED_AT", "UPDATED_BY") VALUES (6, 'Servicio al cliente interno/externo', 'Responde con oportunidad y empatia a las necesidades de clientes internos y externos.', NULL, '2025-09-25 17:03:01.056887', NULL, 'A', '2025-09-25 17:03:01.056887', NULL) ON CONFLICT DO NOTHING;
