INSERT INTO public."COMPETENCY" ("COMPETENCY_ID", "NAME", "DESCRIPTION", "WEIGHT", "CREATED_AT", "CREATED_BY", "STATE", "UPDATED_AT", "UPDATED_BY") VALUES (11, 'Gestion del cambio', 'Se adapta con rapidez a nuevas prioridades, herramientas o procesos y ayuda al equipo a hacerlo.', NULL, '2025-09-25 17:03:01.056887', NULL, 'A', '2025-09-25 17:03:01.056887', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."COMPETENCY" ("COMPETENCY_ID", "NAME", "DESCRIPTION", "WEIGHT", "CREATED_AT", "CREATED_BY", "STATE", "UPDATED_AT", "UPDATED_BY") VALUES (12, 'Dominio tecnico/funcional', 'Aplica conocimientos tecnicos o funcionales clave para ejecutar las tareas de su rol con excelencia.', NULL, '2025-09-25 17:03:01.056887', NULL, 'A', '2025-09-25 17:03:01.056887', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."COMPETENCY" ("COMPETENCY_ID", "NAME", "DESCRIPTION", "WEIGHT", "CREATED_AT", "CREATED_BY", "STATE", "UPDATED_AT", "UPDATED_BY") VALUES (13, 'Gestion de proyectos y tareas', 'Planifica recursos, coordina dependencias y da seguimiento a hitos de proyectos asignados.', NULL, '2025-09-25 17:03:01.056887', NULL, 'A', '2025-09-25 17:03:01.056887', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."COMPETENCY" ("COMPETENCY_ID", "NAME", "DESCRIPTION", "WEIGHT", "CREATED_AT", "CREATED_BY", "STATE", "UPDATED_AT", "UPDATED_BY") VALUES (14, 'Resolucion de problemas', 'Aborda incidencias con criterio, propone alternativas viables y ejecuta soluciones sostenibles.', NULL, '2025-09-25 17:03:01.056887', NULL, 'A', '2025-09-25 17:03:01.056887', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."COMPETENCY" ("COMPETENCY_ID", "NAME", "DESCRIPTION", "WEIGHT", "CREATED_AT", "CREATED_BY", "STATE", "UPDATED_AT", "UPDATED_BY") VALUES (15, 'Responsabilidad y compromiso', 'Asume la propiedad de los resultados, cumple acuerdos y mantiene una conducta etica.', NULL, '2025-09-25 17:03:01.056887', NULL, 'A', '2025-09-25 17:03:01.056887', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."COMPETENCY" ("COMPETENCY_ID", "NAME", "DESCRIPTION", "WEIGHT", "CREATED_AT", "CREATED_BY", "STATE", "UPDATED_AT", "UPDATED_BY") VALUES (31, 'Manejo de maquinas de costura industrial', 'Saber operar correctamente maquinas planas, overlock, recubridora, etc., manteniendo calidad y velocidad.', NULL, '2025-10-08 17:09:27.516142', NULL, 'A', '2025-10-08 17:09:27.516142', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."COMPETENCY" ("COMPETENCY_ID", "NAME", "DESCRIPTION", "WEIGHT", "CREATED_AT", "CREATED_BY", "STATE", "UPDATED_AT", "UPDATED_BY") VALUES (32, 'Control de calidad en la costura', 'Revisar que las prendas no tengan defectos, costuras torcidas, roturas o diferencias en las medidas.', NULL, '2025-10-08 17:09:27.516142', NULL, 'A', '2025-10-08 17:09:27.516142', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."COMPETENCY" ("COMPETENCY_ID", "NAME", "DESCRIPTION", "WEIGHT", "CREATED_AT", "CREATED_BY", "STATE", "UPDATED_AT", "UPDATED_BY") VALUES (33, 'Responsabilidad y puntualidad', 'Cumplir con los horarios, asistir con regularidad y asumir sus tareas sin supervision constante.', NULL, '2025-10-08 17:09:27.516142', NULL, 'A', '2025-10-08 17:09:27.516142', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."COMPETENCY" ("COMPETENCY_ID", "NAME", "DESCRIPTION", "WEIGHT", "CREATED_AT", "CREATED_BY", "STATE", "UPDATED_AT", "UPDATED_BY") VALUES (34, 'Atencion al detalle', 'Detectar errores pequenos en la costura o en el ensamblaje antes de que pasen al siguiente proceso.', NULL, '2025-10-08 17:09:27.516142', NULL, 'A', '2025-10-08 17:09:27.516142', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."COMPETENCY" ("COMPETENCY_ID", "NAME", "DESCRIPTION", "WEIGHT", "CREATED_AT", "CREATED_BY", "STATE", "UPDATED_AT", "UPDATED_BY") VALUES (35, 'Cumplimiento de normas de seguridad y limpieza (5S)', 'Mantener su area ordenada y seguir los procedimientos de seguridad industrial.', NULL, '2025-10-08 17:09:27.516142', NULL, 'A', '2025-10-08 17:09:27.516142', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."COMPETENCY" ("COMPETENCY_ID", "NAME", "DESCRIPTION", "WEIGHT", "CREATED_AT", "CREATED_BY", "STATE", "UPDATED_AT", "UPDATED_BY") VALUES (36, 'Enhebrado y ajuste basico de la maquina', 'Saber preparar su maquina correctamente y solucionar fallas simples sin depender del mecanico.', NULL, '2025-10-08 17:09:27.516142', NULL, 'A', '2025-10-08 17:09:27.516142', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."COMPETENCY" ("COMPETENCY_ID", "NAME", "DESCRIPTION", "WEIGHT", "CREATED_AT", "CREATED_BY", "STATE", "UPDATED_AT", "UPDATED_BY") VALUES (37, 'Compromiso con la produccion y la calidad', 'Trabajar con enfoque en alcanzar las metas y mantener los estandares de calidad de la empresa.', NULL, '2025-10-08 17:09:27.516142', NULL, 'A', '2025-10-08 17:09:27.516142', NULL) ON CONFLICT DO NOTHING;
