INSERT INTO public."MENU_OPTION" ("MENU_OPTION_ID", "NAME", "DESCRIPTION", "PATH", "TYPE", "ICON", "ORDER", "PARENT_ID", "CREATED_AT", "CREATED_BY", "STATE", "UPDATED_AT", "UPDATED_BY", "CONTENT") VALUES ('0-6-1', 'Acerca de', 'Acerca del sistema', '/0-6-1/about', NULL, NULL, 10, '0-6', '2025-09-16 19:43:43', NULL, 'A', '2025-09-16 19:44:57.647867', NULL, '<!DOCTYPE html> <html lang="es">   <head>     <meta charset="UTF-8" />     <title>JW Evalúa • Descripción funcional</title>     <meta name="viewport" content="width=device-width, initial-scale=1.0" />     <style>       :root {         color-scheme: light dark;       }       * {         box-sizing: border-box;       }       body {         margin: 0;         font-family: "Segoe UI", system-ui, -apple-system, sans-serif;         background: #f8fafc;         color: #1f2933;         line-height: 1.6;       }       header {         background: linear-gradient(135deg, #1d4ed8, #3b82f6);         color: #fff;         padding: 3rem 2rem;         text-align: center;       }       header h1 {         margin: 0 0 0.5rem;         font-size: clamp(2rem, 4vw, 2.8rem);       }       header p {         margin: 0.25rem auto;         max-width: 720px;         opacity: 0.85;       }       main {         max-width: 960px;         margin: 0 auto;         padding: 2.5rem 1.5rem 4rem;       }       section h2 {         margin: 2.5rem 0 1rem;         color: #0f172a;         border-bottom: 2px solid #e2e8f0;         padding-bottom: 0.4rem;         font-size: clamp(1.6rem, 3vw, 2rem);       }       article {         margin-top: 1.5rem;         background: #ffffff;         border-radius: 16px;         padding: 1.75rem;         box-shadow: 0 18px 40px rgba(15, 23, 42, 0.08);       }       article h3 {         margin-top: 0;         color: #1d4ed8;         font-size: 1.25rem;       }       p.lead {         font-size: 1.05rem;         margin-bottom: 0.5rem;       }       ul {         margin: 0.5rem 0 0;         padding-left: 1.25rem;       }       li {         margin-bottom: 0.4rem;       }       code {         background: #e2e8f0;         color: #0f172a;         padding: 0.2em 0.45em;         border-radius: 6px;         font-size: 0.95em;       }       footer {         text-align: center;         padding: 2rem 1rem 3rem;         color: #64748b;         font-size: 0.92rem;       }       @media (prefers-color-scheme: dark) {         body {           background: #0f172a;           color: #e2e8f0;         }         header {           background: linear-gradient(135deg, #0b1f51, #1d4ed8);         }         section h2 {           border-color: rgba(226, 232, 240, 0.2);         }         article {           background: #122341;           box-shadow: 0 18px 36px rgba(15, 23, 42, 0.6);         }         code {           background: rgba(148, 163, 184, 0.2);           color: #e0f2fe;         }         footer {           color: #94a3b8;         }       }     </style>   </head>   <body>     <header>       <h1>JW Evalúa</h1>       <p>         Plataforma web para gestionar evaluaciones de desempeño y el         seguimiento de metas por módulos de trabajo, con paneles analíticos,         administración de personal y control de acceso basado en roles.       </p>       <p>         Front-end construido con React + TypeScript + Vite y un diseño         personalizado sobre Ant Design en español.       </p>     </header>      <main>       <section id="resumen">         <h2>Resumen ejecutivo</h2>         <p class="lead">           El proyecto organiza el ciclo de evaluación del talento humano,           agrupando información estratégica en cinco áreas clave:         </p>         <ul>           <li>             <strong>Dashboard</strong>: indicadores y gráficos sobre desempeño             y distribución de personal             (<code>src/pages/dashboard/page.tsx</code>).           </li>           <li>             <strong>Metas por módulo</strong>: planificación, seguimiento y             avance porcentual de objetivos semanales             (<code>src/pages/goals/page.tsx</code>).           </li>           <li>             <strong>Módulos de trabajo</strong>: estructura de equipos, jefes y             miembros asociados             (<code>src/pages/modules/page.tsx</code>).           </li>           <li>             <strong>Empleados</strong>: expediente operativo del personal,             búsquedas y altas (<code>src/pages/employees/page.tsx</code>).           </li>           <li>             <strong>Usuarios y Roles</strong>: gobierno de acceso y estados de             cuentas (<code>src/pages/users/page.tsx</code>,             <code>src/pages/roles/page.tsx</code>).           </li>         </ul>       </section>        <section id="modulos">         <h2>Módulos principales</h2>          <article>           <h3>Panel de control</h3>           <p>             Vista inicial con KPI’s y gráficos construidos con Recharts para             monitorear resultados por área y la distribución de empleados.           </p>           <ul>             <li>               Tarjetas de estado con valores instantáneos de evaluaciones,               alertas y desempeño.             </li>             <li>               <code>BarChart</code> y <code>PieChart</code> permiten explorar               desempeño e integración por departamentos.             </li>             <li>               Componentes personalizados (<code>CustomCard</code>,               <code>CustomDivider</code>) integran la estética propia con Ant               Design.             </li>           </ul>         </article>          <article>           <h3>Gestión de metas por módulo</h3>           <p>             Pestañas por módulo (datos desde <code>useModuleStore</code>) con             filtros avanzados para estado y periodo semanal             (<code>dayjs</code> + semana ISO).           </p>           <ul>             <li>               Tabla inteligente (<code>SmartTable</code>) con búsqueda,               paginación, filtros guardados y acciones contextuales.             </li>             <li>               Seguimiento del progreso usando               <code>CustomProgress</code> y cálculo de cumplimiento.             </li>             <li>               Formularios modales (<code>ModuleGoalForm</code>) respaldados por               <code>useCreateGoalMutation</code> y React Query.             </li>             <li>               Tipos especializados (<code>ModuleSummaryDetail</code>) aseguran               consistencia con la API.             </li>           </ul>         </article>          <article>           <h3>Módulos de trabajo</h3>           <p>             Administración de equipos, supervisores y miembros con posibilidad             de expandir filas para visualizar integrantes.           </p>           <ul>             <li>               Filtros dinámicos construidos con               <code>getConditionFromForm</code> y enviados como               <code>AdvancedCondition</code> al backend.             </li>             <li>               Vistas expandibles muestran listas de miembros con avatares               generados (<code>getAvatarLink</code>).             </li>             <li>               Formularios modales (<code>ModuleForm</code>) para altas y               ediciones, manteniendo estados en               <code>useModuleStore</code>.             </li>           </ul>         </article>          <article>           <h3>Empleados</h3>           <p>             Tabla operativa para la plantilla, con búsqueda por nombre, apellido             o documento y modal para altas.           </p>           <ul>             <li>               El hook <code>useGetPaginatedStaffMutation</code> consulta la API               (<code>API_GET_STAFF_PAGINATION</code>) y sincroniza estado en               <code>useStaffStore</code>.             </li>             <li>               El componente <code>SearchBar</code> combina caja de búsqueda,               botón de creación y contenedor de filtros.             </li>             <li>               Formato de cédulas estandarizado mediante               <code>formatter({ format: ''document'' })</code>.             </li>           </ul>         </article>          <article>           <h3>Usuarios &amp; Roles</h3>           <p>             Gestión de acceso con confirmaciones y notificaciones, integrando             React Query para refrescar datos tras cada cambio.           </p>           <ul>             <li>               Cambios de estado con confirmación modal y mensajes globales               (<code>App.useApp()</code> + <code>NotificationProvider</code>).             </li>             <li>               Reutilización de <code>SmartTable</code> para habilitar/inhabilitar               con íconos semánticos.             </li>             <li>               Separación entre cuentas (<code>useUserStore</code>) y perfiles de               permisos (<code>useRoleStore</code>).             </li>           </ul>         </article>          <article>           <h3>Contenido dinámico &amp; página “Acerca de”</h3>           <p>             Las opciones de menú y el contenido HTML se cargan desde la API,             permitiendo editar textos corporativos sin desplegar código.           </p>           <ul>             <li>               <code>useGetUserMenuOptionsQuery</code> y               <code>useMenuOptionStore</code> persistente (middleware               <code>persist</code> de Zustand) controlan navegación y permisos.             </li>             <li>               <code>currenMenuOption?.CONTENT</code> se inyecta en               <code>src/pages/about/page.tsx</code> para mostrar información               administrable.             </li>           </ul>         </article>          <article>           <h3>Evaluaciones (estado actual)</h3>           <p>             El módulo en <code>src/pages/evaluation/page.tsx</code> actúa como             marcador de posición listo para expandirse con formularios o flujos             de evaluación detallados.           </p>         </article>       </section>        <section id="experiencia">         <h2>Experiencia de usuario</h2>         <article>           <h3>Autenticación y navegación</h3>           <ul>             <li>               Pantalla de acceso con diseño de dos columnas, recordatorio y               recuperación de contraseña               (<code>src/pages/login/page.tsx</code>).             </li>             <li>               Rutas protegidas con <code>AuthGuard</code> / <code>GuestGuard</code> y               redirección inicial a <code>PATH_DASHBOARD</code>.             </li>             <li>               Estructura multi-actividad (<code>/:activityId</code>) para               personalizar el contexto del usuario.             </li>           </ul>         </article>          <article>           <h3>Componentes reutilizables</h3>           <ul>             <li>               <code>SmartTable</code> centraliza búsqueda, filtros, paginación,               acciones y estados visuales uniformes.             </li>             <li>               Biblioteca de <code>Custom*</code> (botones, inputs, modales,               textos) envuelve Ant Design para mantener la identidad visual.             </li>             <li>               <code>useDebounce</code> optimiza búsquedas en vivo y evita cargas               innecesarias sobre los endpoints.             </li>           </ul>         </article>       </section>        <section id="tecnica">         <h2>Arquitectura técnica</h2>         <article>           <h3>Pila tecnológica</h3>           <ul>             <li>               <strong>Frontend:</strong> React 18 + TypeScript + Vite, con               soporte HMR.             </li>             <li>               <strong>UI:</strong> Ant Design (versión española), Styled               Components y componentes customizados.             </li>             <li>               <strong>Estado:</strong> Zustand para stores de dominio               (<code>module.store.ts</code>, <code>user.store.ts</code>, etc.).             </li>             <li>               <strong>Datos remotos:</strong> React Query (<code>useQuery</code>,               <code>useMutation</code>) y un cliente Axios común               (<code>src/services/api.ts</code>).             </li>             <li>               <strong>WebSockets:</strong> cliente resiliente con reconexión               automática (<code>src/web-socket-client.ts</code>) expuesto en               <code>AppContext</code>.             </li>             <li>               <strong>Internacionalización:</strong> Configuración global con               <code>ConfigProvider</code> en español y temas dinámicos               (<code>useLoadTheme</code>).             </li>           </ul>         </article>          <article>           <h3>Comunicaciones con la API</h3>           <ul>             <li>               Endpoints centralizados en               <code>src/constants/routes.ts</code>, usando               <code>BASE_API_PATH</code> y rutas específicas para metas,               usuarios, staff y módulos.             </li>             <li>               Constructores de query string (<code>buildQueryString</code>,               <code>getQueryString</code>) facilitan filtros avanzados.             </li>             <li>               Mutaciones personalizadas (<code>useCustomMutation</code>) devuelven               datos iniciales y manejan errores Axios.             </li>           </ul>         </article>       </section>        <section id="extensibilidad">         <h2>Extensibilidad</h2>         <article>           <h3>Rutas automáticas y metadatos</h3>           <ul>             <li>               <code>import.meta.glob</code> registra automáticamente               <code>page.tsx</code>, <code>page.meta.ts</code> y plantillas,               permitiendo escalar la navegación sin editar el router manualmente.             </li>             <li>               <code>PageMetadata</code> admite banderas como <code>public</code>,               rutas personalizadas y <code>loader</code>s por página.             </li>           </ul>         </article>          <article>           <h3>Próximos pasos sugeridos</h3>           <ul>             <li>               Completar el módulo de Evaluaciones con formularios,               calificaciones y reportes históricos.             </li>             <li>               Conectar alertas en tiempo real aprovechando               <code>WebSocketClient</code> para avisos de metas o evaluaciones.             </li>             <li>               Añadir métricas adicionales al dashboard reutilizando servicios               existentes.             </li>           </ul>         </article>       </section>     </main>      <footer>       Documento generado a partir del repositorio en       <code>src/pages</code>, <code>src/services</code>, <code>src/store</code> y       archivos de configuración relevantes. Última revisión: {{fecha}}.     </footer>   </body> </html>') ON CONFLICT DO NOTHING;
INSERT INTO public."MENU_OPTION" ("MENU_OPTION_ID", "NAME", "DESCRIPTION", "PATH", "TYPE", "ICON", "ORDER", "PARENT_ID", "CREATED_AT", "CREATED_BY", "STATE", "UPDATED_AT", "UPDATED_BY", "CONTENT") VALUES ('0-5-5', 'Producción', 'Producción pro módulo', '/0-5-5/production', NULL, '<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-factory-icon lucide-factory"><path d="M12 16h.01"/><path d="M16 16h.01"/><path d="M3 19a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V8.5a.5.5 0 0 0-.769-.422l-4.462 2.844A.5.5 0 0 1 15 10.5v-2a.5.5 0 0 0-.769-.422L9.77 10.922A.5.5 0 0 1 9 10.5V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2z"/><path d="M8 16h.01"/></svg>', 8, NULL, '2025-07-31 19:51:24.800755', NULL, 'A', '2025-09-12 19:39:28.054971', NULL, NULL) ON CONFLICT DO NOTHING;
